-- migrate:phase expand
-- Foundation schemas, shared vocabularies, and the tenant-context function.
-- Module schemas follow the 0B model `schema` field: the execution module's schema is `exec`.
-- No extensions are required: UUIDv7 keys are generated by the application, and gen_random_uuid()
-- and sha256() are built in (0B §10 allows only widely available extensions when justified).

CREATE SCHEMA exec;
COMMENT ON SCHEMA exec IS 'Execution platform (0B module execution, layer 0): operations, attempts, jobs, outbox, inbox, idempotency, external effects.';
CREATE SCHEMA tenancy;
COMMENT ON SCHEMA tenancy IS 'Workspaces and brands (0B module tenancy). 1A creates only the workspace anchor; 1C extends it.';
CREATE SCHEMA access;
COMMENT ON SCHEMA access IS 'Grants and policy storage (0B module access). Tables arrive in 1D.';
CREATE SCHEMA exec_dispatch;
COMMENT ON SCHEMA exec_dispatch IS 'Payload-free SECURITY DEFINER scheduling functions (0C §12.3-12.4). Owned by pm_scheduler; executable by dispatcher only.';

GRANT USAGE ON SCHEMA exec, tenancy, access TO app_rw, app_worker;
GRANT USAGE ON SCHEMA exec TO pm_scheduler;
GRANT USAGE ON SCHEMA exec_dispatch TO dispatcher;
-- pm_scheduler must be able to own functions in exec_dispatch; it cannot log in.
GRANT USAGE, CREATE ON SCHEMA exec_dispatch TO pm_scheduler;

-- Tenant context (0C §12.2, §12.5). Unset or cleared settings yield NULL, so RLS predicates are NULL
-- and fail closed. Transaction-local `set_config(..., true)` is the only permitted way to set it.
CREATE FUNCTION exec.current_workspace_id() RETURNS uuid
  LANGUAGE sql STABLE PARALLEL SAFE
  AS $$ SELECT NULLIF(current_setting('app.workspace_id', true), '')::uuid $$;
COMMENT ON FUNCTION exec.current_workspace_id() IS 'Transaction-local workspace context; NULL when unset (fail closed).';

-- Internal keys are application-generated UUIDv7 (0B §2.2).
CREATE FUNCTION exec.is_uuidv7(value uuid) RETURNS boolean
  LANGUAGE sql IMMUTABLE PARALLEL SAFE
  AS $$ SELECT substr(value::text, 15, 1) = '7' AND substr(value::text, 20, 1) IN ('8', '9', 'a', 'b') $$;

-- Stable vocabularies as enums (0B §10.3). Values match the 0D registry exactly.
CREATE TYPE exec.actor_type AS ENUM ('human', 'ai', 'automation', 'integration', 'agent', 'system');
CREATE TYPE exec.exec_state AS ENUM ('queued', 'running', 'waiting', 'paused', 'succeeded', 'partial', 'failed', 'cancelled', 'skipped');
CREATE TYPE exec.terminal_reason AS ENUM ('error', 'timed_out', 'limit_exceeded', 'policy_rejected', 'user_cancelled', 'emergency_stop', 'superseded', 'deduplicated');
CREATE TYPE exec.waiting_reason AS ENUM ('approval', 'input', 'rate_limit', 'delay', 'external_confirmation', 'reconciliation_required', 'authorization_changed', 'dependency_unavailable');
CREATE TYPE exec.job_state AS ENUM ('queued', 'leased', 'retry_scheduled', 'succeeded', 'dead', 'cancelled');
CREATE TYPE exec.job_error_class AS ENUM ('transient', 'deterministic', 'authorization', 'policy', 'worker_lost', 'timeout');
CREATE TYPE exec.effect_state AS ENUM ('pending', 'sent', 'unknown', 'confirmed', 'failed', 'cancelled');
CREATE TYPE exec.effect_destination_class AS ENUM ('idempotent_by_provider', 'naturally_idempotent', 'deduplicated_by_receiver', 'unsafe');
CREATE TYPE exec.idempotency_state AS ENUM ('in_progress', 'completed', 'failed_deterministic');
CREATE TYPE exec.risk_class AS ENUM ('R0', 'R1', 'R2', 'R3', 'R4');
CREATE TYPE exec.data_class AS ENUM ('C0', 'C1', 'C2', 'C3', 'C4');

-- 0C principals that can appear in tenant execution context (platform-only principals excluded).
CREATE DOMAIN exec.principal_type AS text
  CONSTRAINT principal_type_known CHECK (VALUE IN (
    'account', 'member', 'guest', 'team', 'api_token_personal', 'service_principal', 'oauth_client',
    'integration_connection', 'inbound_webhook', 'automation', 'ai_action', 'agent_profile',
    'agent_run', 'tool_invocation', 'system_job'));
